-- -----------------------------------------------------------------------------
-- 1) CHECK constraints (business invariants)
-- -----------------------------------------------------------------------------

-- Jobs: an OPEN job carries no closing data; an UNAVAILABLE job must record its outcome
-- and closing time (FR-2.3.4, FR-2.3.5). A hired seeker is only allowed with HIRED_VIA_PLATFORM.
ALTER TABLE "jobs" ADD CONSTRAINT "jobs_closing_consistency_chk" CHECK (
    ("status" = 'OPEN' AND "closed_outcome" IS NULL AND "closed_at" IS NULL AND "hired_seeker_id" IS NULL)
 OR ("status" = 'UNAVAILABLE' AND "closed_outcome" IS NOT NULL AND "closed_at" IS NOT NULL)
);
ALTER TABLE "jobs" ADD CONSTRAINT "jobs_hired_seeker_outcome_chk" CHECK (
    "hired_seeker_id" IS NULL OR "closed_outcome" = 'HIRED_VIA_PLATFORM'
);
ALTER TABLE "jobs" ADD CONSTRAINT "jobs_min_years_chk" CHECK ("min_years_experience" BETWEEN 0 AND 60);

ALTER TABLE "seeker_profiles" ADD CONSTRAINT "seeker_profiles_years_chk" CHECK (
    "years_of_experience" IS NULL OR "years_of_experience" BETWEEN 0 AND 60
);
-- No experience => no years recorded.
ALTER TABLE "seeker_profiles" ADD CONSTRAINT "seeker_profiles_experience_consistency_chk" CHECK (
    "has_experience" IS DISTINCT FROM FALSE OR "years_of_experience" IS NULL
);

ALTER TABLE "persons" ADD CONSTRAINT "persons_birth_date_chk" CHECK ("birth_date" >= DATE '1900-01-01');

ALTER TABLE "seeker_educations" ADD CONSTRAINT "seeker_educations_graduation_year_chk" CHECK (
    "graduation_year" IS NULL OR "graduation_year" BETWEEN 1950 AND 2100
);

ALTER TABLE "experience_positions" ADD CONSTRAINT "experience_positions_dates_chk" CHECK (
    "end_date" IS NULL OR "end_date" >= "start_date"
);

ALTER TABLE "match_scores" ADD CONSTRAINT "match_scores_score_chk" CHECK ("score" BETWEEN 0 AND 100);

-- Files: max 10MB (architecture section 8).
ALTER TABLE "uploaded_files" ADD CONSTRAINT "uploaded_files_size_chk" CHECK ("size_bytes" > 0 AND "size_bytes" <= 10485760);

ALTER TABLE "email_verification_codes" ADD CONSTRAINT "email_verification_codes_attempts_chk" CHECK (
    "attempts" >= 0 AND "attempts" <= "max_attempts" + 1
);

ALTER TABLE "employers" ADD CONSTRAINT "employers_approval_consistency_chk" CHECK (
    "approval_status" <> 'APPROVED' OR "approved_at" IS NOT NULL
);

ALTER TABLE "users" ADD CONSTRAINT "users_email_lowercase_chk" CHECK ("email" = lower("email"));

-- -----------------------------------------------------------------------------
-- 2) audit_log is append-only (FR-2.4.2, architecture section 8)
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION "audit_log_block_mutation"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only: % is not allowed', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "audit_log_no_update_delete"
    BEFORE UPDATE OR DELETE ON "audit_log"
    FOR EACH ROW EXECUTE FUNCTION "audit_log_block_mutation"();

CREATE TRIGGER "audit_log_no_truncate"
    BEFORE TRUNCATE ON "audit_log"
    FOR EACH STATEMENT EXECUTE FUNCTION "audit_log_block_mutation"();

-- Defence in depth: no implicit write privileges for other roles. In production the API should
-- connect as a non-owner role granted only SELECT, INSERT on audit_log (see docs/database.md).
REVOKE UPDATE, DELETE, TRUNCATE ON "audit_log" FROM PUBLIC;

-- -----------------------------------------------------------------------------
-- 3) Aggregate reporting views (FR-2.5.1, FR-2.5.2). No personal data: counts only.
--    The minimum group size (settings key reports.minGroupSize, default 5) is applied
--    by the reports module before display; views return raw counts.
-- -----------------------------------------------------------------------------

-- Base set of countable seekers: active, verified account, not soft-deleted, personal step done.
CREATE VIEW "v_report_seeker_base" AS
SELECT
    sp."id"                  AS "seeker_id",
    p."gender"               AS "gender",
    date_part('year', age(CURRENT_DATE, p."birth_date"))::int AS "age_years",
    p."dar_id"               AS "dar_id",
    sp."has_experience"      AS "has_experience",
    sp."years_of_experience" AS "years_of_experience"
FROM "seeker_profiles" sp
JOIN "users"   u ON u."id" = sp."user_id"
JOIN "persons" p ON p."id" = sp."person_id"
WHERE sp."deleted_at" IS NULL
  AND p."deleted_at"  IS NULL
  AND u."deleted_at"  IS NULL
  AND u."status" = 'ACTIVE';

COMMENT ON VIEW "v_report_seeker_base" IS
  'Internal building block for seeker reports. Not exposed directly: carries seeker_id. Use the v_report_seekers_* views.';

CREATE VIEW "v_report_seekers_total" AS
SELECT count(*)::int AS "seeker_count" FROM "v_report_seeker_base";

CREATE VIEW "v_report_seekers_by_age_band" AS
SELECT
    b."band"  AS "age_band",
    b."ord"   AS "sort_order",
    count(*)::int AS "seeker_count"
FROM (
    SELECT
        CASE
            WHEN "age_years" < 18 THEN 'UNDER_18'
            WHEN "age_years" < 25 THEN '18_24'
            WHEN "age_years" < 35 THEN '25_34'
            WHEN "age_years" < 45 THEN '35_44'
            WHEN "age_years" < 55 THEN '45_54'
            ELSE '55_PLUS'
        END AS "band",
        CASE
            WHEN "age_years" < 18 THEN 0
            WHEN "age_years" < 25 THEN 1
            WHEN "age_years" < 35 THEN 2
            WHEN "age_years" < 45 THEN 3
            WHEN "age_years" < 55 THEN 4
            ELSE 5
        END AS "ord"
    FROM "v_report_seeker_base"
) b
GROUP BY b."band", b."ord";

CREATE VIEW "v_report_seekers_by_gender" AS
SELECT "gender", count(*)::int AS "seeker_count"
FROM "v_report_seeker_base"
GROUP BY "gender";

-- Highest education level per seeker (by rank); seekers without education => UNSPECIFIED.
CREATE VIEW "v_report_seekers_by_education_level" AS
SELECT
    COALESCE(el."code", 'UNSPECIFIED') AS "education_level_code",
    el."name_ar"                       AS "name_ar",
    el."name_en"                       AS "name_en",
    COALESCE(el."rank", -1)            AS "sort_order",
    count(*)::int                      AS "seeker_count"
FROM "v_report_seeker_base" s
LEFT JOIN LATERAL (
    SELECT l."code", l."name_ar", l."name_en", l."rank"
    FROM "seeker_educations" e
    JOIN "education_levels" l ON l."id" = e."education_level_id"
    WHERE e."seeker_id" = s."seeker_id" AND e."deleted_at" IS NULL
    ORDER BY l."rank" DESC
    LIMIT 1
) el ON TRUE
GROUP BY el."code", el."name_ar", el."name_en", el."rank";

CREATE VIEW "v_report_seekers_by_experience_band" AS
SELECT b."band" AS "experience_band", b."ord" AS "sort_order", count(*)::int AS "seeker_count"
FROM (
    SELECT
        CASE
            WHEN "has_experience" IS NULL          THEN 'UNSPECIFIED'
            WHEN "has_experience" = FALSE          THEN 'NONE'
            WHEN "years_of_experience" IS NULL     THEN 'UNSPECIFIED'
            WHEN "years_of_experience" <= 2        THEN '0_2'
            WHEN "years_of_experience" <= 5        THEN '3_5'
            WHEN "years_of_experience" <= 10       THEN '6_10'
            ELSE '11_PLUS'
        END AS "band",
        CASE
            WHEN "has_experience" IS NULL          THEN 9
            WHEN "has_experience" = FALSE          THEN 0
            WHEN "years_of_experience" IS NULL     THEN 9
            WHEN "years_of_experience" <= 2        THEN 1
            WHEN "years_of_experience" <= 5        THEN 2
            WHEN "years_of_experience" <= 10       THEN 3
            ELSE 4
        END AS "ord"
    FROM "v_report_seeker_base"
) b
GROUP BY b."band", b."ord";

CREATE VIEW "v_report_seekers_by_dar" AS
SELECT
    COALESCE(d."code", 'UNSPECIFIED') AS "dar_code",
    d."name_ar"                       AS "name_ar",
    d."name_en"                       AS "name_en",
    COALESCE(d."sort_order", 2147483647) AS "sort_order",
    count(*)::int                     AS "seeker_count"
FROM "v_report_seeker_base" s
LEFT JOIN "dars" d ON d."id" = s."dar_id"
GROUP BY d."code", d."name_ar", d."name_en", d."sort_order";

-- Countable jobs: not soft-deleted, employer not soft-deleted.
CREATE VIEW "v_report_job_base" AS
SELECT j."id" AS "job_id", j."sector_id", j."status", j."closed_outcome"
FROM "jobs" j
JOIN "employers" e ON e."id" = j."employer_id"
WHERE j."deleted_at" IS NULL AND e."deleted_at" IS NULL;

COMMENT ON VIEW "v_report_job_base" IS
  'Internal building block for job reports. Use the v_report_jobs_* views.';

CREATE VIEW "v_report_jobs_by_sector" AS
SELECT
    s."code"     AS "sector_code",
    s."name_ar"  AS "name_ar",
    s."name_en"  AS "name_en",
    s."sort_order" AS "sort_order",
    count(*)::int AS "job_count",
    count(*) FILTER (WHERE j."status" = 'OPEN')::int                             AS "open_count",
    count(*) FILTER (WHERE j."status" = 'UNAVAILABLE')::int                      AS "unavailable_count",
    count(*) FILTER (WHERE j."closed_outcome" = 'HIRED_VIA_PLATFORM')::int       AS "hired_via_platform_count",
    count(*) FILTER (WHERE j."closed_outcome" = 'CLOSED_WITHOUT_HIRING')::int    AS "closed_without_hiring_count"
FROM "v_report_job_base" j
JOIN "sectors" s ON s."id" = j."sector_id"
GROUP BY s."code", s."name_ar", s."name_en", s."sort_order";

CREATE VIEW "v_report_jobs_by_status" AS
SELECT "status", count(*)::int AS "job_count"
FROM "v_report_job_base"
GROUP BY "status";

CREATE VIEW "v_report_jobs_by_outcome" AS
SELECT "closed_outcome", count(*)::int AS "job_count"
FROM "v_report_job_base"
WHERE "status" = 'UNAVAILABLE'
GROUP BY "closed_outcome";
